// Selected official ActivityDomainBossPreviewContent; generated by prepare_activity_battle_page_support.py.
using Zjcs.Official.WorldUI;
using Zjcs.Official.ProfessionUI;
namespace Zjcs.Official.ActivityBattleUI
{
using Object = UnityEngine.Object;
using System;
using UnityEngine;
using UnityEngine.UI;

public class ActivityDomainBossPreviewContent : MonoBehaviour
{
	private enum State
	{
		Charging,
		Countdown
	}

	[SerializeField]
	private Slider mProgressSlider;

	[SerializeField]
	private WorldMultiLanguageText mProgressText;

	[SerializeField]
	private CountdownText mCountdown;

	[SerializeField]
	private float mFillLerpSpeed = 1f;

	[SerializeField]
	private WorldStateSwitcher<State> mStateSwitcher;

	private System.Func<float> mPreviewProgress;
	public System.Func<DateTime> Clock { private get; set; } = () => DateTime.Now;

	private DateTime mSummonTime;


	private bool mInited;

	private bool mCountdownStarted;

	private Action mOnSummonReached;

	private bool mSummonReachedNotified;

	public void Init(System.Func<float> previewProgress, DateTime summonTime, Action onSummonReached)
	{
		mPreviewProgress = previewProgress ?? throw new ArgumentNullException(nameof(previewProgress));
		mSummonTime = summonTime;
		mOnSummonReached = onSummonReached;
		mCountdownStarted = false;
		mSummonReachedNotified = false;
		mInited = true;
		float targetFill = GetTargetFill();
		if ((Object)(object)mProgressSlider != (Object)null)
		{
			mProgressSlider.value = targetFill;
		}
		RefreshProgressText(targetFill);
		RefreshFullState(targetFill);
	}

	private void Update()
	{
		if (mInited)
		{
			NotifySummonReachedIfNeeded();
			float targetFill = GetTargetFill();
			if ((Object)(object)mProgressSlider != (Object)null)
			{
				mProgressSlider.value = Mathf.MoveTowards(mProgressSlider.value, targetFill, mFillLerpSpeed * Time.deltaTime);
			}
			RefreshProgressText(((Object)(object)mProgressSlider != (Object)null) ? mProgressSlider.value : targetFill);
			RefreshFullState(targetFill);
		}
	}

	private void NotifySummonReachedIfNeeded()
	{
		if (!mSummonReachedNotified && !(Clock() < mSummonTime))
		{
			mSummonReachedNotified = true;
			mOnSummonReached?.Invoke();
		}
	}

	private float GetTargetFill()
	{
		return Mathf.Clamp01(mPreviewProgress() / 100f);
	}

	private void RefreshProgressText(float fill01)
	{
		string text = Zjcs.Official.World.NativeLabelUI.Framework.NumberFormatHelper.FormatSpecifySignificantPercent(fill01, 2, "%", '.');
		mProgressText.Format(text);
	}

	private void RefreshFullState(float target01)
	{
		bool flag = target01 >= 1f;
		if (flag && !mCountdownStarted)
		{
			mCountdownStarted = true;
			if ((Object)(object)mCountdown != (Object)null)
			{
				DateTime dateTime = Clock();
				TimeSpan duration = mSummonTime - dateTime;
				mCountdown.Show(duration, null);
			}
		}
		State state = (flag ? State.Countdown : State.Charging);
		mStateSwitcher.SetState(state);
	}
}

}
